/* CheckObra 2.0 · frontend responsive, Supabase Auth / RLS / Realtime */
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.CHECKOBRA_CONFIG||{},configured=cfg.supabaseUrl?.startsWith('https://')&&!cfg.supabaseUrl.includes('TU-')&&cfg.supabaseAnonKey&&!cfg.supabaseAnonKey.includes('TU_');
const db=configured?window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey):null;
const S={user:null,profile:null,tab:'inicio',units:[],trades:[],tasks:[],issues:[],progress:[],documents:[],rdis:[],proposals:[],checklist:[],baseline:[],excelStatus:[],staff:[],people:[],floor:8,unit:'802',point:null,filter:'',docCategory:'Planos',advanceTrade:'',advanceFloor:'todos',fieldStatus:[],frontStatus:[],knowledgeArticles:[],knowledgeQuestions:[],knowledgeSearch:'',knowledgeCategory:'Todas',manualIndex:null,manualCatalog:null,manualAnswer:'',manualQuestion:'',manualLoading:false,releaseMode:'depto',releaseFloor:'7',releaseTrade:'',releaseRoom:'',releaseUnits:[]};
const TYPES={'01':'A','02':'B1','03':'D','04':'C','05':'B','06':'A1'};
const ROOMS=['Acceso','Estar / comedor','Cocina','Dormitorio principal','Dormitorio 2','Dormitorio 3','Baño principal','Baño secundario','Terraza','Logia','Pasillo','Clóset','Otro'];
const ELEMENTS=['Muro','Cielo','Piso','Ventana','Puerta','Mueble','Artefacto','Revestimiento','Otro'];
const KINDS=['Daño','Faltante','Defecto de ejecución','Funcionamiento','Terminación','Otro'];
const STAFF=[['Paul González','jefatura'],['Cristóbal Candia','jefatura'],['Constanza Reyes','oficina_tecnica'],['Vicente Bizama','calidad'],['Marcelo Campos','supervisor'],['José Labraña','supervisor'],['Nicole Jacques','supervisor'],['Paulina Cruces','supervisor'],['Felipe Tobar','supervisor'],['Sergio Bravo','supervisor'],['Carlos Suárez','supervisor'],['Luciano Hoppe','logistica']];
const role=()=>S.profile?.role||'',manager=()=>role()==='jefatura',quality=()=>role()==='calidad',technical=()=>role()==='oficina_tecnica';
function toast(msg){const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>t.style.display='none',4200)}
function opt(values,selected){return values.map(v=>{let value=Array.isArray(v)?v[0]:v,label=Array.isArray(v)?v[1]:v;return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`}).join('')}
function val(id){return document.getElementById(id)?.value?.trim()||''}
function card(title,body){return `<section class="panel"><h2>${title}</h2>${body}</section>`}
function badge(status){let cls=['Cerrada','Validada','Aprobada','Cumple'].includes(status)?'green':['Abierta','Rechazada','No cumple'].includes(status)?'red':'amber';return `<span class="tag ${cls}">${esc(status)}</span>`}
function date(v){return v?new Date(v).toLocaleDateString('es-CL'):'—'}
function ownerName(id,fallback){return S.people.find(p=>p.id===id)?.full_name||fallback||'Sin asignar'}
function staffOptions(){return [['','Sin asignar'],...S.staff.filter(p=>p.active).map(p=>[p.full_name,p.full_name])]}
function staffProfile(name){return S.people.find(p=>p.full_name===name)?.id||null}
function staffOptions(){return [['','Sin asignar'],...S.staff.filter(p=>p.active).map(p=>[p.full_name,p.full_name])]}
function staffProfile(name){return S.people.find(p=>p.full_name===name)?.id||null}
function unitIds(f){return S.units.filter(u=>u.floor===Number(f)).map(u=>u.id)}
function metric(label,n){return `<div class="metric"><span class="muted">${label}</span><b>${n}</b></div>`}
async function query(table){const {data,error}=await db.from(table).select('*').limit(2500);if(error)throw Error(`${table}: ${error.message}`);return data||[]}
async function reload(){if(!S.user)return;try{const tables=['profiles','units','trades','tasks','issues','progress','documents','rdis','checklist_proposals','checklist_items','schedule_baseline','excel_status','staff_directory','field_status','front_status','knowledge_articles','knowledge_questions'];const data=await Promise.all(tables.map(query));[S.people,S.units,S.trades,S.tasks,S.issues,S.progress,S.documents,S.rdis,S.proposals,S.checklist,S.baseline,S.excelStatus,S.staff,S.fieldStatus,S.frontStatus,S.knowledgeArticles,S.knowledgeQuestions]=data;S.profile=S.people.find(p=>p.id===S.user.id)||null;render()}catch(e){toast('Error de sincronización: '+e.message);console.error(e)}}
async function mutate(table,payload,mode='insert',id){try{let q=db.from(table);const {error}=mode==='update'?await q.update(payload).eq('id',id):await q.insert(payload);if(error)throw error;await reload();toast('Guardado y sincronizado')}catch(e){toast('No se pudo guardar: '+e.message)}}
async function rpc(fn,args){try{const {error}=await db.rpc(fn,args);if(error)throw error;await reload();toast('Operación realizada')}catch(e){toast('No autorizado o error: '+e.message)}}
function nav(){const tabs=[['inicio','▦ Inicio'],['semana','▣ Semana'],['avance','▥ Obra / Avance'],['frentes','▤ Fachada / Cubierta'],['observaciones','⌖ Observaciones / R1'],['calidad','✓ Calidad'],['tecnica','▤ Oficina Técnica'],['biblioteca','▣ Biblioteca del Saber'],['trabajo','☷ Mi trabajo'],['admin','⚙ Administración']];return `<nav class="nav">${tabs.filter(t=>t[0]!=='admin'||manager()).map(([k,l])=>`<button class="${S.tab===k?'active':''}" onclick="switchTab('${k}')">${l}</button>`).join('')}</nav>`}
function switchTab(t){S.tab=t;render()}
function render(){const app=$('#app');if(!configured){app.innerHTML=card('Configuración de servidor pendiente',`<p>La aplicación está preparada para sincronización en vivo, pero falta conectar un proyecto Supabase. Copia <code>config.example.js</code> a <code>config.js</code> y configura URL y clave pública. Lee <b>INSTALACION.md</b>.</p><p class="notice">Sin conexión a servidor no se presentan datos simulados como reales.</p>`);return}
if(!S.user){app.innerHTML=card('Acceso seguro',`<p>Ingresa con el correo corporativo autorizado. Las cuentas son personales y los permisos se aplican en el servidor.</p><form onsubmit="signIn(event)"><label>Correo</label><input type="email" id="loginEmail" autocomplete="email" required><label>Contraseña</label><input type="password" id="loginPassword" autocomplete="current-password" required><div class="actions"><button class="primary">Ingresar</button><button type="button" onclick="resetPassword()">Recuperar contraseña</button></div></form><p class="muted">Solicita tu invitación a Paul o Cristóbal. No existen contraseñas precargadas.</p>`);$('#identity').textContent='Acceso privado';return}
$('#identity').innerHTML=`<span>${esc(S.profile?.full_name||S.user.email)}</span> <button onclick="signOut()">Salir</button>`;
app.innerHTML=nav()+({inicio:home,semana:week,avance:advance,frentes:frontView,observaciones:observations,calidad:qualityView,tecnica:technicalView,biblioteca:knowledgeView,trabajo:myWork,admin:adminView}[S.tab]||home)()+`<footer>CheckObra 2.5 · Registros compartidos · ${esc(role())} · Castellón 227</footer>`;
if(S.tab==='observaciones')bindPlan();if(S.tab==='biblioteca')loadManualIndex();}
async function signIn(e){e.preventDefault();const {error}=await db.auth.signInWithPassword({email:val('loginEmail'),password:val('loginPassword')});if(error)toast(error.message)}
async function resetPassword(){const email=val('loginEmail');if(!email)return toast('Escribe tu correo primero');const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin});toast(error?error.message:'Si el correo está autorizado, recibirás instrucciones')}
async function signOut(){await db.auth.signOut();S.user=null;S.profile=null;render()}
function home(){const pending=S.issues.filter(i=>i.status!=='Cerrada');const finished=S.tasks.filter(t=>t.status==='Validada');const reviews=S.tasks.filter(t=>t.status==='Por revisar');const observedUnits=new Set(pending.map(i=>i.unit_id).filter(Boolean));return card('Tablero de Jefatura',`<div class="grid">${metric('Observaciones pendientes',pending.length)}${metric('Deptos. con pendientes',observedUnits.size)}${metric('Compromisos validados',finished.length)}${metric('Tareas por revisar',reviews.length)}${metric('RDI abiertas',S.rdis.filter(r=>r.status!=='Cerrada').length)}${metric('Cambios checklist pendientes',S.proposals.filter(p=>p.status==='Pendiente').length)}</div><p class="notice">Avance histórico del Excel: ${S.excelStatus.filter(x=>x.status==='Ejecutado').length} actividades ejecutadas, ${S.excelStatus.filter(x=>x.status==='En proceso').length} en proceso y ${S.excelStatus.filter(x=>x.status==='Con observaciones').length} con observaciones. Consulta Obra / Avance para ver el detalle por partida, piso y departamento. Son estados registrados en el archivo, no una inspección física actual.</p>`)+card('Accesos rápidos',`<div class="actions"><button onclick="switchTab('observaciones')">Registrar observación</button><button onclick="switchTab('semana')">Compromisos semanales</button><button onclick="switchTab('tecnica')">Documentos y RDI</button><button onclick="switchTab('biblioteca')">Biblioteca del Saber</button><button onclick="switchTab('calidad')">Inspecciones y checklists</button></div>`)+card('Pendientes recientes',S.issues.filter(i=>i.status!=='Cerrada').slice(-8).reverse().map(i=>`<div class="card"><b>${esc(i.unit_id||i.front)} · ${esc(i.room)}</b> ${badge(i.status)}<p>${esc(i.detail)}</p><span class="muted">${esc(ownerName(i.owner_id,i.owner_name))}</span></div>`).join('')||'<p class="muted">Sin observaciones registradas.</p>')}
function week(){const mine=!manager();const rows=S.tasks.filter(t=>!mine||t.owner_id===S.user.id);return card('Compromisos semanales',`${manager()?`<form onsubmit="createTask(event)"><div class="grid2"><div><label>Compromiso</label><input id="taskTitle" required></div><div><label>Responsable</label><select id="taskOwner">${opt(S.staff.filter(p=>p.active).map(p=>[p.full_name,p.full_name]))}</select></div><div><label>Partida</label><select id="taskTrade">${opt([['','Sin partida'],...S.trades.map(t=>[t.id,t.name])])}</select></div><div><label>Fecha compromiso</label><input type="date" id="taskDue" required></div><div><label>Departamento (opcional)</label><select id="taskUnit">${opt([['','General'],...S.units.map(u=>[u.id,u.id])])}</select></div></div><button class="primary">Asignar compromiso</button></form><hr>`:''}<div class="scroll"><table><thead><tr><th>Compromiso</th><th>Responsable</th><th>Fecha</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.title)}</b><div class="muted">${esc(t.unit_id||t.sector||'General')}</div></td><td>${esc(ownerName(t.owner_id,t.owner_name))}</td><td>${date(t.due_date)}</td><td>${badge(t.status)}</td><td>${manager()&&t.status==='Por revisar'?`<button onclick="reviewTask('${t.id}',true)">Validar</button><button onclick="reviewTask('${t.id}',false)">Rechazar</button>`:t.owner_id===S.user.id&&['Pendiente','En ejecución','Rechazada'].includes(t.status)?`<button onclick="completeTask('${t.id}')">Declarar terminado</button>`:''}</td></tr>`).join('')}</tbody></table></div>`)}
async function createTask(e){e.preventDefault();const name=val('taskOwner');await mutate('tasks',{title:val('taskTitle'),owner_id:staffProfile(name),owner_name:name,trade_id:val('taskTrade')||null,unit_id:val('taskUnit')||null,due_date:val('taskDue')})}
async function completeTask(id){await mutate('tasks',{status:'Por revisar',finished_at:new Date().toISOString()},'update',id)}
async function reviewTask(id,ok){const notes=ok?null:prompt('Motivo obligatorio de rechazo');if(!ok&&!notes?.trim())return;await mutate('tasks',{status:ok?'Validada':'Rechazada',validated_at:ok?new Date().toISOString():null,validated_by:ok?S.user.id:null,notes},'update',id)}
function advanceExplorer(){
 const trades=S.trades.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'es'));
 const selected=trades.some(t=>String(t.id)===String(S.advanceTrade))?S.advanceTrade:(trades[0]?.id||'');
 S.advanceTrade=selected;
 const trade=trades.find(t=>String(t.id)===String(selected));
 const units=S.units.filter(u=>Number(u.floor)>=2&&Number(u.floor)<=17).sort((a,b)=>Number(a.floor)-Number(b.floor)||String(a.id).localeCompare(String(b.id)));
 const floorIds=[...new Set(units.map(u=>Number(u.floor)))].sort((a,b)=>a-b);
 const rows=S.progress.filter(p=>String(p.trade_id)===String(selected)&&p.unit_id);
 const stateOf=(id)=>{const override=S.fieldStatus.find(x=>String(x.trade_id)===String(selected)&&String(x.unit_id)===String(id)&&!x.room);if(override)return override.status==='Ejecutado'?'ok':override.status==='En proceso'?'proceso':override.status==='Con observaciones'?'obs':'sin';const r=rows.filter(p=>String(p.unit_id)===String(id));
  if(r.length){const completed=r.some(p=>p.supervisor_closed===true || (Number(p.total)>0&&Number(p.executed)>=Number(p.total)));
   if(completed)return 'ok';if(r.some(p=>Number(p.executed)>0))return 'proceso';}
  const imported=S.excelStatus.find(x=>String(x.trade_id)===String(selected)&&String(x.unit_id)===String(id));
  return imported?.status==='Ejecutado'?'ok':imported?.status==='Con observaciones'?'obs':imported?.status==='En proceso'?'proceso':'sin';};
 const stats={ok:0,proceso:0,obs:0,sin:0};units.forEach(u=>stats[stateOf(u.id)]++);
 const full=floorIds.filter(f=>{const us=units.filter(u=>Number(u.floor)===f);return us.length&&us.every(u=>stateOf(u.id)==='ok')});
 let consecutive=null;for(const f of floorIds){if(full.includes(f))consecutive=f;else break}
 const highest=units.filter(u=>stateOf(u.id)==='ok').reduce((m,u)=>Math.max(m,Number(u.floor)),0);
 const filtered=floorIds.filter(f=>S.advanceFloor==='todos'||Number(S.advanceFloor)===f);
 const summary=`<div class="grid">${metric('Departamentos terminados',stats.ok+' / '+units.length)}${metric('En proceso',stats.proceso)}${metric('Con observaciones',stats.obs)}${metric('Con ejecución hasta piso',highest||'—')}${metric('Cierre continuo hasta piso',consecutive||'—')}${metric('Sin ejecución registrada',stats.sin)}${metric('Partida seleccionada',trade?.name||'Sin partidas')}</div>`;
 const grid=filtered.map(f=>{const us=units.filter(u=>Number(u.floor)===f);const n=us.filter(u=>stateOf(u.id)==='ok').length;return `<div class="advance-floor"><div class="row"><b>Piso ${f}</b><span class="muted">${n} / ${us.length} terminados</span></div><div class="advance-units">${us.map(u=>{const st=stateOf(u.id);return `<span class="advance-unit ${st}" title="Depto ${esc(u.id)}: ${st==='ok'?'Ejecutado':st==='proceso'?'En proceso':st==='obs'?'Con observaciones':'Sin ejecución registrada'}">${esc(u.id)}<small>${st==='ok'?'✓':st==='proceso'?'◐':st==='obs'?'!':'—'}</small></span>`}).join('')}</div></div>`}).join('');
 return card('¿Hasta dónde está ejecutada una partida?',`<div class="grid2"><div><label>Filtrar por partida</label><select onchange="S.advanceTrade=this.value;render()">${opt(trades.map(t=>[t.id,t.name]),selected)}</select></div><div><label>Filtrar por piso</label><select onchange="S.advanceFloor=this.value;render()">${opt([['todos','Todos los pisos'],...floorIds.map(f=>[String(f),'Piso '+f])],S.advanceFloor)}</select></div></div>${summary}<div class="advance-legend"><span><i class="legend-ok"></i> Ejecutado</span><span><i class="legend-proceso"></i> En proceso</span><span><i class="legend-obs"></i> Con observaciones</span><span><i class="legend-sin"></i> Sin registro</span></div><div class="advance-floors">${grid||'<p class="muted">No hay departamentos cargados en Supabase. Debes importar el catálogo de unidades.</p>'}</div><p class="muted">Se calcula con los registros de avance cargados en Supabase. Los colores del Excel se muestran tras ejecutar la migración. Las confirmaciones de terreno y las liberaciones nuevas tienen prioridad sobre el Excel, conservando su fuente. «Cierre continuo» exige todos los departamentos de cada piso desde el piso 2.</p>`);
}
function advance(){let imported=S.excelStatus.length,importedOk=S.excelStatus.filter(x=>x.status==='Ejecutado').length,importedProcess=S.excelStatus.filter(x=>x.status==='En proceso').length,importedObs=S.excelStatus.filter(x=>x.status==='Con observaciones').length;let actual=S.progress.reduce((n,p)=>n+Number(p.executed||0),0),total=S.progress.reduce((n,p)=>n+Number(p.total||0),0);return card('Avance registrado en Excel',`<div class="grid">${metric('Actividades importadas',imported)}${metric('Ejecutadas (verde)',importedOk)}${metric('En proceso (celeste)',importedProcess)}${metric('Con observaciones (amarillo)',importedObs)}${metric('Ejecución entre registros coloreados',imported?Math.round(importedOk/imported*100)+'%':'Sin datos')}</div><p class="muted">Porcentaje calculado solamente entre actividades con estado importado; no es el avance ponderado total de la obra. Selecciona una partida abajo para conocer el último piso ejecutado y los departamentos pendientes.</p>`)+advanceExplorer()+card('Avance declarado en la aplicación',`<div class="grid">${metric('Registros de avance',S.progress.length)}${metric('Ejecución declarada',total?Math.round(actual/total*100)+'%':'Sin datos')}${metric('Registros de programa',S.baseline.length)}</div><p class="notice">El avance declarado por supervisores, el cierre de Calidad y el programa son indicadores independientes. Los estados del Excel se muestran arriba como avance histórico registrado. Los avances nuevos declarados en la aplicación se muestran por separado.</p>`)+releaseView()+card('Registros',`<div class="scroll"><table><tr><th>Partida</th><th>Ubicación</th><th>Ejecutado</th><th>Supervisor</th></tr>${S.progress.map(p=>`<tr><td>${esc(S.trades.find(t=>t.id===p.trade_id)?.name)}</td><td>${esc(p.unit_id||p.sector)}</td><td>${esc(p.executed)} / ${esc(p.total)} ${esc(p.measure)}</td><td>${p.supervisor_closed?'Terminada':'En ejecución'}</td></tr>`).join('')}</table></div>`)+card('Línea base de programa',S.baseline.length?`<div class="scroll"><table><tr><th>Partida</th><th>Ubicación</th><th>Inicio</th><th>Término</th><th>Verificado</th></tr>${S.baseline.slice(0,100).map(p=>`<tr><td>${esc(p.trade_label)}</td><td>${esc(p.location)}</td><td>${esc(p.start_date||'')}</td><td>${esc(p.end_date||'')}</td><td>${p.verified?'Sí':'No'}</td></tr>`).join('')}</table></div>`:'<p class="muted">Programa aún no importado a la base de datos. Se incluye archivo original para preparación y validación de línea base.</p>')}
async function saveProgress(e){e.preventDefault();const trade_id=val('prTrade');if(!trade_id)return toast('No tienes partidas asignadas');const total=Number(val('prTotal')),executed=Number(val('prDone'));if(executed>total)return toast('La cantidad ejecutada no puede superar el total');await mutate('progress',{trade_id,unit_id:val('prUnit')||null,sector:val('prSector')||null,measure:val('prMeasure'),total,executed,supervisor_closed:$('#prClosed').checked,reported_by:S.user.id})}

function releaseView(){
 const available=S.trades.filter(t=>manager()||t.owner_id===S.user.id);
 const trade=available.some(t=>String(t.id)===String(S.releaseTrade))?S.releaseTrade:(available[0]?.id||'');S.releaseTrade=trade;
 const floor=Number(S.releaseFloor||7),units=S.units.filter(u=>Number(u.floor)===floor).sort((a,b)=>String(a.id).localeCompare(String(b.id)));
 const mode=S.releaseMode;
 const buttons=units.map(u=>`<button type="button" class="release-unit ${S.releaseUnits.includes(u.id)?'picked':''}" onclick="toggleReleaseUnit('${esc(u.id)}')">${esc(u.id)} ${S.releaseUnits.includes(u.id)?'✓':''}</button>`).join('');
 return card('Liberar avance · A + B + C',`<p class="muted">Producción declara ejecutado; Calidad verifica por separado. Cada cambio conserva fecha y usuario en Supabase.</p><div class="release-tabs"><button class="${mode==='depto'?'active':''}" onclick="S.releaseMode='depto';render()">A · Deptos</button><button class="${mode==='piso'?'active':''}" onclick="S.releaseMode='piso';render()">B · Piso completo</button><button class="${mode==='recinto'?'active':''}" onclick="S.releaseMode='recinto';render()">C · Recinto</button></div><div class="grid2"><div><label>Partida</label><select onchange="S.releaseTrade=this.value;render()">${opt(available.map(t=>[t.id,t.name]),trade)}</select></div><div><label>Piso</label><select onchange="S.releaseFloor=this.value;S.releaseUnits=[];render()">${opt(Array.from({length:16},(_,i)=>[String(i+2),'Piso '+(i+2)]),String(floor))}</select></div></div>${mode==='piso'?`<p class="notice">Se marcarán como ejecutados los ${units.length} departamentos del piso ${floor}, previa confirmación.</p>`:`<label>${mode==='recinto'?'Departamento':'Seleccionar departamentos'}</label><div class="release-units">${buttons}</div>`}${mode==='recinto'?`<label>Recinto / sector</label><select id="releaseRoom">${opt(ROOMS,S.releaseRoom)}</select><p class="muted">La ejecución de un recinto no libera el departamento completo.</p>`:''}<label>Estado a registrar</label><select id="releaseStatus">${opt(['Ejecutado','En proceso','Con observaciones','Sin ejecutar'])}</select><div class="actions"><button class="primary" onclick="submitRelease()">${mode==='piso'?'Liberar piso completo':'Guardar estados seleccionados'}</button></div><p class="muted">Se conserva el estado importado del Excel como referencia histórica. Los estados nuevos prevalecen en el explorador de avance.</p>`);
}
function toggleReleaseUnit(id){if(S.releaseMode==='recinto')S.releaseUnits=[id];else S.releaseUnits=S.releaseUnits.includes(id)?S.releaseUnits.filter(x=>x!==id):[...S.releaseUnits,id];render()}
async function submitRelease(){const mode=S.releaseMode,trade=S.releaseTrade,floor=Number(S.releaseFloor),room=mode==='recinto'?val('releaseRoom'):'';
 if(!trade)return toast('Selecciona una partida asignada');const units=mode==='piso'?S.units.filter(u=>Number(u.floor)===floor).map(u=>u.id):S.releaseUnits;
 if(!units.length)return toast('Selecciona departamentos');if(mode==='recinto'&&units.length!==1)return toast('Selecciona un solo departamento');
 const status=val('releaseStatus');if(mode==='piso'&&!confirm(`¿Confirmas ${status} para los ${units.length} departamentos del piso ${floor}?`))return;
 if(mode==='piso'&&status==='Ejecutado'){const pending=S.issues.filter(i=>units.includes(i.unit_id)&&i.status!=='Cerrada'&&(!i.trade_id||String(i.trade_id)===String(trade)));if(pending.length&&!confirm(`Hay ${pending.length} observaciones abiertas asociadas a este piso. ¿Registrar ejecución de producción de todos modos? Calidad seguirá pendiente.`))return;}
 const rows=units.map(unit_id=>({trade_id:trade,unit_id,room,status,source:'Liberación aplicación',updated_by:S.user.id,updated_at:new Date().toISOString()}));
 try{const {error}=await db.from('field_status').upsert(rows,{onConflict:'trade_id,unit_id,room'});if(error)throw error;S.releaseUnits=[];await reload();toast(`${rows.length} registros guardados`)}catch(e){toast('Error al liberar: '+e.message)}
}
function frontView(){const rows=S.frontStatus.slice().sort((a,b)=>a.front.localeCompare(b.front)||a.zone.localeCompare(b.zone)||a.activity.localeCompare(b.activity));const roof=['Estructura shaft','Cerchas','Aislación','Placas','Hojalatería','Cubierta','Igol Primer','Igol Denso','Cerámicos'];return card('Cubierta · control por tramo',`<p class="notice">Solo se consideran ejecutados los hitos confirmados. No se presume que toda actividad anterior esté terminada.</p><div class="grid">${['Tramo 1','Tramo 2','Tramo 3'].map(z=>`<div class="metric"><b>${z}</b>${rows.filter(r=>r.front==='Cubierta'&&r.zone===z).map(r=>`<p>${esc(r.activity)}: ${badge(r.status)}</p>`).join('')||'<p>Sin registros</p>'}</div>`).join('')}</div><p class="muted">Secuencia de actividades a controlar: ${roof.join(' · ')}. Los hitos no confirmados no se marcan automáticamente como ejecutados.</p>`)+card('Fachada · estado por frente y actividad',`<p class="muted">Los datos de las hojas complementarias deben validarse por frente, nivel y actividad antes de considerarse ejecutados.</p>${frontTable('Fachada')}`)+card('Administrar avance de frentes',`${manager()?`<div class="grid2"><div><label>Frente</label><select id="frontType">${opt(['Cubierta','Fachada'])}</select></div><div><label>Tramo / orientación / piso</label><input id="frontZone" placeholder="Ej. Tramo 1 / Sur piso 8"></div><div><label>Actividad</label><input id="frontActivity" placeholder="Ej. Igol Primer"></div><div><label>Estado</label><select id="frontState">${opt(['Ejecutado','En proceso','Con observaciones','Pendiente'])}</select></div></div><label>Detalle</label><input id="frontDetail" placeholder="Observaciones o respaldo"><button class="primary" onclick="saveFront()">Guardar avance de frente</button>`:'<p>La actualización de frentes está habilitada para Jefatura.</p>'}`)+card('Registros de fachada y cubierta',frontTable('Todos'))}
function frontTable(front){const rows=S.frontStatus.filter(r=>front==='Todos'||r.front===front);return rows.length?`<div class="scroll"><table><tr><th>Frente</th><th>Zona</th><th>Actividad</th><th>Estado</th><th>Detalle</th></tr>${rows.map(r=>`<tr><td>${esc(r.front)}</td><td>${esc(r.zone)}</td><td>${esc(r.activity)}</td><td>${badge(r.status)}</td><td>${esc(r.detail||'—')}</td></tr>`).join('')}</table></div>`:'<p class="muted">Sin estados verificados registrados.</p>'}
async function saveFront(){if(!manager())return toast('Solo Jefatura');const zone=val('frontZone'),activity=val('frontActivity');if(!zone||!activity)return toast('Completa zona y actividad');const payload={front:val('frontType'),zone,activity,status:val('frontState'),detail:val('frontDetail')||null,source:'Actualización aplicación',updated_by:S.user.id,updated_at:new Date().toISOString()};const {error}=await db.from('front_status').upsert(payload,{onConflict:'front,zone,activity'});if(error)return toast('Error: '+error.message);await reload();toast('Frente actualizado')}
function observations(){const u=S.units.find(x=>x.id===S.unit);const selected=S.issues.filter(i=>i.unit_id===S.unit);const floorUnits=unitIds(S.floor);return card('Mapa de observaciones',`<div class="grid2"><div><label>Piso</label><select onchange="S.floor=Number(this.value);S.unit=unitIds(S.floor)[0];S.point=null;render()">${opt(Array.from({length:16},(_,i)=>[i+2,'Piso '+(i+2)]),S.floor)}</select></div><div><label>Departamento</label><select onchange="S.unit=this.value;S.point=null;render()">${opt(floorUnits.map(v=>[v,'Departamento '+v]),S.unit)}</select></div></div><p class="notice">Departamento ${esc(S.unit)} · Tipología ${esc(u?.typology)} · Plano ${esc(u?.plan)}. Toca el plano para colocar el punto exacto del defecto.</p><div class="mapwrap"><div class="mapinner" id="planArea"><img src="/assets/${S.floor===2?'A05':'A06'}.jpg" alt="Plano de arquitectura de piso ${S.floor}"><div id="planPins">${S.issues.filter(i=>i.floor===S.floor&&i.point_x!=null).map(i=>`<button class="pin ${i.status==='Corregida'?'corrected':i.status==='Cerrada'?'closed':''}" style="left:${Number(i.point_x)}%;top:${Number(i.point_y)}%" title="${esc(i.unit_id+' · '+i.room+' · '+i.detail)}" onclick="event.stopPropagation();openIssue('${i.id}')">!</button>`).join('')}${S.point?`<span class="pin" style="left:${S.point.x}%;top:${S.point.y}%;background:#2563eb;pointer-events:none">+</span>`:''}</div></div></div><p class="muted">El plano representa el piso completo. Verifica visualmente que el punto esté dentro del departamento seleccionado.</p>`)+card('Registrar observación',`<form onsubmit="createIssue(event)"><div class="grid2"><div><label>Recinto</label><select id="isRoom">${opt(ROOMS)}</select></div><div><label>Elemento</label><select id="isElement">${opt(ELEMENTS)}</select></div><div><label>Tipo</label><select id="isKind">${opt(KINDS)}</select></div><div><label>Responsable</label><select id="isOwner">${opt([['','Por asignar'],...S.staff.filter(p=>p.role==='supervisor'&&p.active).map(p=>[p.full_name,p.full_name])])}</select></div><div><label>Partida</label><select id="isTrade">${opt([['','Sin partida'],...S.trades.map(t=>[t.id,t.name])])}</select></div><div><label>Ubicación exacta (obligatoria)</label><input id="isWhere" required placeholder="Muro norte, 20 cm del marco"></div></div><label>Descripción</label><textarea id="isDetail" required placeholder="Describe el daño, falta o defecto"></textarea><label>Fotografía (recomendado)</label><input id="isPhoto" type="file" accept="image/*" capture="environment"><button class="primary">Registrar observación</button></form>`)+card(`Observaciones del departamento ${esc(S.unit)} (${selected.length})`,selected.map(issueCard).join('')||'<p class="muted">Sin observaciones registradas. Esto no significa que esté inspeccionado.</p>')}
function bindPlan(){const area=$('#planArea');if(!area)return;area.addEventListener('click',e=>{if(e.target.closest('.pin'))return;const r=area.getBoundingClientRect();S.point={x:Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))};const pins=$('#planPins');pins.insertAdjacentHTML('beforeend',`<span class="pin" id="newPin" style="left:${S.point.x}%;top:${S.point.y}%;background:#2563eb;pointer-events:none">+</span>`);document.querySelectorAll('#newPin').forEach((p,i)=>{if(i)p.remove()});toast('Ubicación marcada en plano')})}
async function uploadFile(file,prefix){if(!file)return null;if(file.size>25*1024*1024)throw Error('Archivo mayor a 25 MB');const safeName=file.name.replace(/[^a-zA-Z0-9_.-]/g,'_');const path=`${prefix}/${crypto.randomUUID()}-${safeName}`;const {error}=await db.storage.from('checkobra-files').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(error)throw error;return path}
async function createIssue(e){e.preventDefault();if(!S.point)return toast('Debes marcar el punto sobre el plano');try{const ownerNameSelected=val('isOwner');const photo=await uploadFile($('#isPhoto').files[0],'observaciones');await mutate('issues',{unit_id:S.unit,floor:S.floor,room:val('isRoom'),element:val('isElement'),kind:val('isKind'),position_note:val('isWhere'),detail:val('isDetail'),point_x:S.point.x,point_y:S.point.y,owner_id:staffProfile(ownerNameSelected),owner_name:ownerNameSelected||null,trade_id:val('isTrade')||null,photo_path:photo});S.point=null}catch(err){toast(err.message)}}
function issueCard(i){const mine=i.owner_id===S.user.id;return `<div class="card"><div class="row"><b>${esc(i.unit_id||i.front)} · ${esc(i.room)} · ${esc(i.element)}</b>${badge(i.status)}</div><p>${esc(i.detail)}</p><p class="muted">📍 ${esc(i.position_note)} · ${esc(i.kind)} · ${esc(ownerName(i.owner_id,i.owner_name))}</p><div class="actions">${i.photo_path?`<button onclick="viewFile('${esc(i.photo_path)}')">Foto inicial</button>`:''}${i.correction_path?`<button onclick="viewFile('${esc(i.correction_path)}')">Foto corrección</button>`:''}${i.unit_id?`<button onclick="goUnit('${esc(i.unit_id)}')">Ver en plano</button>`:''}${(mine||manager()||quality())&&['Abierta','En corrección'].includes(i.status)?`<button onclick="correctIssue('${i.id}')">Solicitar verificación</button>`:''}${quality()&&i.status==='Corregida'?`<button onclick="reviewIssue('${i.id}',true)">Cerrar conforme</button><button onclick="reviewIssue('${i.id}',false)">Rechazar corrección</button>`:''}</div></div>`}
function goUnit(id){S.floor=Number(id.slice(0,-2));S.unit=id;S.tab='observaciones';render()}
function openIssue(id){const i=S.issues.find(x=>x.id===id);if(!i)return;toast(`${i.unit_id||i.front} · ${i.room} · ${i.position_note}: ${i.detail}`)}
async function viewFile(path){const {data,error}=await db.storage.from('checkobra-files').createSignedUrl(path,120);if(error)return toast(error.message);window.open(data.signedUrl,'_blank','noopener')}
async function correctIssue(id){const file=await pickFile('Adjunta fotografía de la corrección (opcional)');if(file===false)return;try{const path=file?await uploadFile(file,'correcciones'):null;await rpc('change_issue_status',{p_id:id,p_next:'Corregida',p_correction_path:path})}catch(e){toast(e.message)}}
async function reviewIssue(id,approve){if(!approve&&!confirm('¿Rechazar corrección y devolver observación a Abierta?'))return;await rpc('change_issue_status',{p_id:id,p_next:approve?'Cerrada':'Abierta'})}
function pickFile(message){return new Promise(resolve=>{const f=document.createElement('input');f.type='file';f.accept='image/*';f.style.display='none';document.body.append(f);f.onchange=()=>{const file=f.files[0]||null;f.remove();resolve(file)};f.oncancel=()=>{f.remove();resolve(false)};toast(message);f.click()})}
function qualityView(){const pending=S.proposals.filter(p=>p.status==='Pendiente');return card('Control de Calidad',`<div class="grid">${metric('Ítems de checklist',S.checklist.filter(x=>x.active).length)}${metric('Solicitudes pendientes',pending.length)}${metric('Observaciones por verificar',S.issues.filter(x=>x.status==='Corregida').length)}</div><p class="notice">Las inspecciones de Calidad y las observaciones no se confunden con el avance físico. Solo Calidad verifica y cierra observaciones.</p>`)+card('Propuestas de cambio de checklist',`${quality()?`<form onsubmit="proposeChecklist(event)"><div class="grid2"><div><label>Partida</label><select id="ckTrade">${opt(S.trades.map(t=>[t.id,t.name]))}</select></div><div><label>Acción</label><select id="ckAction" onchange="document.getElementById('ckItemWrap').style.display=this.value==='Agregar'?'none':'block'">${opt(['Agregar','Modificar','Quitar'])}</select></div></div><div id="ckItemWrap" style="display:none"><label>Ítem existente</label><select id="ckItem">${opt(S.checklist.filter(i=>i.active).map(i=>[i.id,i.title]))}</select></div><label>Texto nuevo del ítem</label><input id="ckTitle"><label>Criterio técnico</label><textarea id="ckCriterion"></textarea><label>Motivo de solicitud (obligatorio)</label><textarea id="ckReason" required></textarea><button class="primary">Enviar propuesta a Jefatura</button></form><hr>`:''}<div class="scroll"><table><tr><th>Acción</th><th>Propuesta</th><th>Estado</th><th>Revisión</th></tr>${S.proposals.slice().reverse().map(p=>`<tr><td>${esc(p.action)}</td><td>${esc(p.proposed_title||S.checklist.find(i=>i.id===p.item_id)?.title||'Ítem existente')}<div class="muted">${esc(p.reason)}</div></td><td>${badge(p.status)}</td><td>${manager()&&p.status==='Pendiente'?`<button onclick="reviewProposal('${p.id}',true)">Aprobar</button> <button onclick="reviewProposal('${p.id}',false)">Rechazar</button>`:esc(p.review_note||'—')}</td></tr>`).join('')}</table></div>`)+card('Ítems vigentes',`<div class="scroll"><table><tr><th>Partida</th><th>Control</th><th>Versión</th></tr>${S.checklist.filter(i=>i.active).map(i=>`<tr><td>${esc(S.trades.find(t=>t.id===i.trade_id)?.name)}</td><td>${esc(i.title)}</td><td>${i.version}</td></tr>`).join('')}</table></div><p class="muted">La carga íntegra de los checklists aprobados se debe verificar contra el registro técnico antes de publicar la primera versión.</p>`)}
async function proposeChecklist(e){e.preventDefault();const action=val('ckAction');if(action==='Agregar'&&!val('ckTitle'))return toast('Escribe el ítem');await mutate('checklist_proposals',{trade_id:val('ckTrade'),action,item_id:action==='Agregar'?null:val('ckItem')||null,proposed_title:val('ckTitle')||null,proposed_criterion:val('ckCriterion')||null,reason:val('ckReason')})}
async function reviewProposal(id,approve){const note=prompt(approve?'Comentario de aprobación (opcional)':'Motivo de rechazo (obligatorio)')||'';if(!approve&&!note.trim())return;await rpc('review_checklist_proposal',{p_id:id,p_approve:approve,p_note:note})}


/* Biblioteca 2.5: recuperación documental local, respuestas verificables y sin inventar cifras.
   No envía datos a servicios externos ni requiere clave de IA. */
const MANUAL_URL='/biblioteca/CDT_Manual_Tolerancias_Edificaciones_3ed_2018.pdf';
const manualNormalize=t=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const manualStop=new Set('de del la las los el en un una para por que cual como cuanto cuales y o a al es se sobre tiene tienen instalacion mostrar muestrame dime necesito tolerancia tolerancias revisar revision criterio criterios partida manual'.split(' '));
const manualWords=t=>manualNormalize(t).replace(/[^a-z0-9ñ ]/g,' ').split(/\s+/).filter(w=>w.length>2&&!manualStop.has(w));
function manualAssistantView(){return card('Asistente técnico · Manual CDT 2018',`<p class="muted">Pregunta por una partida. Se mostrarán criterios concretos y páginas del manual, sin obligarte a recorrer el PDF.</p><form onsubmit="askManual(event)"><label>¿Qué necesitas revisar?</label><div class="grid2"><input id="manualQuestion" placeholder="Ej.: tolerancias para instalar cerámicos" value="${esc(S.manualQuestion)}" required><button class="primary">Consultar manual</button></div></form><div class="actions"><button onclick="manualQuick('Tolerancias de cerámicos')">Cerámicos</button><button onclick="manualQuick('Tolerancias de tabiques')">Tabiques</button><button onclick="manualQuick('Tolerancias de ventanas')">Ventanas</button><button onclick="manualQuick('Tolerancias de puertas')">Puertas</button><button onclick="manualQuick('Tolerancias de pinturas')">Pinturas</button></div><div id="manualAnswer">${S.manualAnswer||'<p class="notice">Selecciona una partida o escribe tu consulta. El manual se indexa al entrar en esta sección.</p>'}</div><p class="muted" style="font-size:.85rem">Fuente: CDT, Manual de Tolerancias para Edificaciones, 3.ª edición (2018). Los valores son referenciales: verificar EETT del proyecto, normativa obligatoria y funcionalidad.</p>`)}
async function loadManualIndex(){if(S.manualIndex)return;try{const [r,c]=await Promise.all([fetch('/biblioteca/manual_cdt_index.json'),fetch('/biblioteca/manual_cdt_catalog.json')]);if(!r.ok||!c.ok)throw Error('No se encontraron los índices técnicos');S.manualIndex=(await r.json()).pages;S.manualCatalog=await c.json();const target=document.querySelector('#manualAnswer');if(target&&!S.manualAnswer)target.innerHTML='<p class="notice">Manual listo para consultar. Escribe tu pregunta.</p>'}catch(e){const t=document.querySelector('#manualAnswer');if(t)t.innerHTML=`<p class="notice">No fue posible cargar el índice: ${esc(e.message)}</p>`}}
function manualQuick(q){const t=document.querySelector('#manualQuestion');if(t)t.value=q;manualLookup(q)}
function askManual(e){e.preventDefault();manualLookup(document.querySelector('#manualQuestion')?.value||'')}
async function manualLookup(question){S.manualQuestion=question;const target=document.querySelector('#manualAnswer');if(!target)return;target.innerHTML='<p class="notice">Buscando la partida y sus criterios en el manual…</p>';await loadManualIndex();if(!S.manualIndex){target.innerHTML='<p class="notice">No se puede consultar el manual en este momento.</p>';return}
 const words=manualWords(question);if(!words.length){target.innerHTML='<p class="notice">Indica una partida o característica técnica.</p>';return}
 const ceramics=words.some(w=>/ceramic|porcelanat|palmeta|canteria|adhesiv|fragüe|frague/.test(w));
 if(ceramics){S.manualAnswer=manualCeramics(question);target.innerHTML=S.manualAnswer;return}
 const hits=S.manualIndex.map(p=>{const norm=manualNormalize(p.text),score=words.reduce((a,w)=>a+(norm.includes(w)?(norm.split(w).length-1>2?3:2):0),0);return {...p,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);
 if(!hits.length){S.manualAnswer='<p class="notice">No encontré un criterio verificable para esa pregunta en el Manual CDT. Puedes registrar una consulta para Calidad u Oficina Técnica.</p>';target.innerHTML=S.manualAnswer;return}
 const catalog=(S.manualCatalog||[]).map(c=>({...c,score:manualWords(c.name+' '+c.terms).reduce((a,w)=>a+(words.some(q=>w.startsWith(q)||q.startsWith(w))?1:0),0)})).sort((a,b)=>b.score-a.score)[0];
 let relevant=hits;if(catalog?.score>0){const filtered=hits.filter(p=>p.page>=catalog.start&&p.page<=catalog.end);if(filtered.length)relevant=filtered}
 S.manualAnswer=`<h3>${esc(catalog?.score>0?catalog.name:'Resultados documentales')}</h3><p class="notice">Se localizaron pasajes del manual. Estos extractos no son una interpretación normativa ni una respuesta generada por IA. Abre la página para confirmar el contexto y los valores.</p>`+relevant.map(p=>{const norm=manualNormalize(p.text);let idx=Math.max(0,Math.min(...words.map(w=>{const n=norm.indexOf(w);return n<0?999999:n})));if(idx===999999)idx=0;const extract=p.text.slice(Math.max(0,idx-100),Math.min(p.text.length,idx+550));return `<div class="card"><b>Página ${p.page} del PDF</b><p>${esc(extract)}…</p><a href="${MANUAL_URL}#page=${p.page}" target="_blank" rel="noopener">Ver página fuente ↗</a></div>`}).join('');target.innerHTML=S.manualAnswer;
}
function manualCeramics(q){const appearance=/aspect|defect|tono|tonalidad|quebrad|fisura|esmalte|visual/.test(manualNormalize(q));const method=/como|revis|verific|medir|inspec|herramient/.test(manualNormalize(q));const entries=[['Desnivel entre palmetas en pisos','Máximo 1 mm entre bordes de palmetas contiguas'],['Desnivel entre palmetas en otras superficies','Máximo 2 mm entre bordes'],['Contacto efectivo del adhesivo','Mínimo 70 % de la superficie de la palmeta, tanto en pisos como en otras superficies'],['Alineación de canterías','± 2 mm en 3 m, en ambos sentidos'],['Espesor de canterías','± 2 mm respecto del espesor especificado']];return `<div class="card"><span class="tag green">Criterios localizados</span><h3>Revestimientos cerámicos y porcelanatos</h3><p class="muted">Capítulo 10 · Tabla 2 · Página impresa 30 / página 31 del PDF</p><div class="scroll"><table><tr><th>Criterio</th><th>Tolerancia CDT</th></tr>${entries.map(x=>`<tr><td>${esc(x[0])}</td><td><b>${esc(x[1])}</b></td></tr>`).join('')}</table></div><a href="${MANUAL_URL}#page=31" target="_blank" rel="noopener">Ver tabla original (página 31 del PDF) ↗</a></div><div class="card"><h3>Cómo verificar en terreno</h3><p><b>Aspecto:</b> inspeccionar con luz día o iluminación definitiva a 1 m de la superficie.</p><p><b>Planeidad y desniveles:</b> usar regla adecuada y medir la diferencia con instrumento graduado.</p><p><b>Contacto del adhesivo:</b> el manual propone golpes ligeros con un instrumento metálico y evaluación del sonido; advierte que el sustrato puede modificarlo. Esta prueba no cuantifica por sí sola el porcentaje de cobertura.</p><p><b>Canterías:</b> revisar alineación con regla o lienza y espesor con regla graduada perpendicular.</p><a href="${MANUAL_URL}#page=31" target="_blank" rel="noopener">Ver procedimiento (página 31 del PDF) ↗</a></div><div class="card"><h3>Aspecto y defectos</h3><p>La tabla 1 incluye límites para variaciones de tonalidad y defectos superficiales; las palmetas quebradas, despuntadas, agrietadas o con zonas sin esmalte no se aceptan. Ver las condiciones particulares de cada defecto en la tabla original.</p><a href="${MANUAL_URL}#page=30" target="_blank" rel="noopener">Ver tabla de aspecto (página 30 del PDF) ↗</a></div><p class="notice"><b>Aplicación:</b> valores referenciales CDT, no reemplazan las EETT de Castellón 227 ni la normativa obligatoria. Manual publicado en 2018; verificar vigencia y eventuales exigencias particulares.</p>`}

/* Biblioteca del Saber: búsqueda local sobre fuentes verificadas, preguntas y revisión técnica.
   No presenta respuestas generadas por IA sin una integración y fuentes verificables. */
function knowledgeView(){
 const term=S.knowledgeSearch.trim().toLocaleLowerCase('es');
 const cat=S.knowledgeCategory;
 const articles=S.knowledgeArticles.filter(a=>a.published && (cat==='Todas'||a.category===cat) && (!term||[a.title,a.summary,a.content,a.category,a.source_title].join(' ').toLocaleLowerCase('es').includes(term)));
 const docs=S.documents.filter(d=>(!term||[d.title,d.code,d.category,d.revision].join(' ').toLocaleLowerCase('es').includes(term))&&(cat==='Todas'||cat==='Documentos'));
 const categories=['Todas','Tolerancias','Cómo revisar','Manuales y fichas','Normativa','Procedimientos','Documentos'];
 const own=S.knowledgeQuestions.filter(q=>manager()||technical()||quality()||q.created_by===S.user.id);
 const mayReview=manager()||technical()||quality();
 return manualAssistantView()+card('Biblioteca del Saber · Consulta técnica',`<p>Consulta tolerancias, procedimientos de inspección, fichas técnicas, manuales y documentos vigentes. <b>Las respuestas publicadas deben tener respaldo documental.</b></p><div class="notice">La búsqueda consulta documentos y respuestas validadas. El asistente superior consulta el texto del Manual CDT por partida y página. Sin una clave de IA configurada, entrega coincidencias documentales y criterios verificados; no genera respuestas libres con un modelo de IA.</div><div class="grid2"><div><label>Buscar conocimiento</label><input id="knowledgeSearch" placeholder="Ej. cerámicos, fijaciones, impermeabilización" value="${esc(S.knowledgeSearch)}" oninput="S.knowledgeSearch=this.value;knowledgeRefresh()"></div><div><label>Categoría</label><select id="knowledgeCategory" onchange="S.knowledgeCategory=this.value;knowledgeRefresh()">${opt(categories,S.knowledgeCategory)}</select></div></div><div id="knowledgeResults">${knowledgeResults(articles,docs)}</div>`)
 +card('Haz una pregunta técnica',`<p class="muted">Toda la obra puede preguntar. Calidad, Oficina Técnica o Jefatura podrán responder con el criterio, procedimiento y fuente aplicable.</p><form onsubmit="submitKnowledgeQuestion(event)"><label>Pregunta</label><textarea id="knowledgeQuestion" required maxlength="1200" placeholder="Ej.: ¿Cómo debo comprobar la planeidad del cerámico de piso?"></textarea><label>Partida o contexto (opcional)</label><input id="knowledgeContext" maxlength="200" placeholder="Ej.: cerámicos, baño, piso 7"><button class="primary">Enviar consulta</button></form>`)
 +card(mayReview?'Consultas técnicas · Revisión y respuesta':'Mis consultas técnicas',own.length?`<div class="scroll"><table><tr><th>Pregunta</th><th>Estado</th><th>Respuesta y respaldo</th><th>Acción</th></tr>${own.slice().reverse().map(q=>`<tr><td><b>${esc(q.question)}</b><div class="muted">${esc(q.context||'')} · ${date(q.created_at)}</div></td><td>${badge(q.status)}</td><td>${q.answer?`<div>${esc(q.answer).replace(/\n/g,'<br>')}</div><div class="muted">Fuente: ${esc(q.source_reference||'No indicada')}</div>`:'Pendiente de respuesta validada'}</td><td>${mayReview?`<button onclick="answerKnowledgeQuestion('${q.id}')">Responder / revisar</button>`:''}</td></tr>`).join('')}</table></div>`:'<p class="muted">No hay consultas registradas.</p>')
 +(mayReview?card('Publicar conocimiento validado',`<p class="muted">Solo se publicarán criterios que incluyan una fuente verificable. No copiar tolerancias sin confirmar su norma, ficha o EETT.</p><form onsubmit="publishKnowledgeArticle(event)"><label>Título</label><input id="knowledgeTitle" required maxlength="180"><label>Categoría</label><select id="knowledgeNewCategory">${opt(categories.filter(c=>!['Todas','Documentos'].includes(c)))}</select><label>Resumen</label><input id="knowledgeSummary" required maxlength="500"><label>Procedimiento / criterio técnico</label><textarea id="knowledgeContent" required></textarea><label>Documento fuente y versión</label><input id="knowledgeSource" required placeholder="Ej.: EETT Arquitectura, Rev. 2, sección 5.3"><button class="primary">Publicar contenido validado</button></form>`):'');
}
function knowledgeResults(articles,docs){const manualVisible=(S.knowledgeCategory==='Todas'||S.knowledgeCategory==='Tolerancias'||S.knowledgeCategory==='Documentos'||S.knowledgeCategory==='Manuales y fichas')&&(!S.knowledgeSearch.trim()||'manual tolerancias edificaciones cdt cchc 2018 hormigón albañilería losas radieres tabiques cielos estucos yeso cerámicos escaleras puertas ventanas papel madera guardapolvos alfombras cornisas cubrejuntas pilastras closets muebles pinturas pavimentos pisos artefactos eléctricos'.includes(S.knowledgeSearch.trim().toLocaleLowerCase('es')));const manualCard=manualVisible?`<div class="card"><span class="tag">Tolerancias · Fuente externa</span> <b>Manual de Tolerancias para Edificaciones — CDT, 3ª edición (2018)</b><p>Documento Técnico CDT N°42 · 69 páginas PDF · Referencia técnica para criterios de tolerancias y métodos de verificación. Las EETT del proyecto y normativa obligatoria vigente deben revisarse antes de aplicar un valor.</p><a href="/biblioteca/CDT_Manual_Tolerancias_Edificaciones_3ed_2018.pdf" target="_blank" rel="noopener noreferrer">Abrir manual completo (PDF)</a><div class="muted">Fuente: Corporación de Desarrollo Tecnológico (CDT) / CChC · Edición 2018 · Referencia, no EETT aprobada del proyecto. El asistente superior indexa el texto de las páginas del manual.</div></div>`:'';return `<div class="grid">${metric('Respuestas publicadas',articles.length)}${metric('Documentos encontrados',docs.length)}${metric('Preguntas sin responder',S.knowledgeQuestions.filter(q=>q.status==='Pendiente').length)}</div><h3>Respuestas técnicas verificadas</h3>${articles.length?articles.map(a=>`<div class="card"><span class="tag">${esc(a.category)}</span> <b>${esc(a.title)}</b><p>${esc(a.summary)}</p><details><summary>Ver criterio y fuente</summary><p class="knowledge-pre">${esc(a.content)}</p><p class="muted">Fuente: ${esc(a.source_title)} ${a.source_revision?'· '+esc(a.source_revision):''}</p></details></div>`).join(''):'<p class="muted">No hay respuestas validadas para esta búsqueda. Puedes enviar una pregunta.</p>'}<h3>Manuales técnicos de referencia</h3>${manualCard||'<p class="muted">No hay manuales coincidentes.</p>'}<h3>Documentos de Oficina Técnica</h3>${docs.length?docs.map(d=>`<div class="card"><b>${esc(d.title)}</b> <span class="tag">${esc(d.category)}</span><div class="muted">${esc(d.code||'')} · ${esc(d.revision||'Sin revisión')} ${d.is_current?'· Vigente':''}</div><button onclick="viewFile('${esc(d.file_path)}')">Abrir documento</button></div>`).join(''):'<p class="muted">No hay documentos coincidentes.</p>'}`}
function knowledgeRefresh(){const t=$('#knowledgeResults');if(!t)return;const term=S.knowledgeSearch.trim().toLocaleLowerCase('es'),cat=S.knowledgeCategory;const a=S.knowledgeArticles.filter(x=>x.published&&(cat==='Todas'||x.category===cat)&&(!term||[x.title,x.summary,x.content,x.category,x.source_title].join(' ').toLocaleLowerCase('es').includes(term)));const d=S.documents.filter(x=>(cat==='Todas'||cat==='Documentos')&&(!term||[x.title,x.code,x.category,x.revision].join(' ').toLocaleLowerCase('es').includes(term)));t.innerHTML=knowledgeResults(a,d)}
async function submitKnowledgeQuestion(e){e.preventDefault();const question=val('knowledgeQuestion');if(question.length<8)return toast('Describe la consulta con más detalle');await mutate('knowledge_questions',{question,context:val('knowledgeContext')||null,created_by:S.user.id,status:'Pendiente'})}
async function answerKnowledgeQuestion(id){const q=S.knowledgeQuestions.find(x=>x.id===id);if(!q)return;const answer=prompt('Respuesta técnica (Cancelar para salir):',q.answer||'');if(answer===null)return;if(!answer.trim())return toast('La respuesta no puede quedar vacía');const source=prompt('Fuente documental exacta (obligatoria):',q.source_reference||'');if(source===null)return;if(!source.trim())return toast('Indica la fuente y versión');await mutate('knowledge_questions',{answer:answer.trim(),source_reference:source.trim(),status:'Respondida',answered_by:S.user.id,answered_at:new Date().toISOString()},'update',id)}
async function publishKnowledgeArticle(e){e.preventDefault();const title=val('knowledgeTitle'),content=val('knowledgeContent'),source=val('knowledgeSource');if(!source)return toast('Debes indicar la fuente documental');await mutate('knowledge_articles',{title,category:val('knowledgeNewCategory'),summary:val('knowledgeSummary'),content,source_title:source,published:true,created_by:S.user.id})}

function technicalView(){return card('Oficina Técnica · Biblioteca documental',`<div class="grid">${metric('Documentos',S.documents.length)}${metric('RDI propuestas',S.rdis.filter(r=>r.status==='Propuesta').length)}${metric('RDI sin cerrar',S.rdis.filter(r=>r.status!=='Cerrada').length)}</div>${technical()?`<form onsubmit="uploadDocument(event)"><div class="grid2"><div><label>Nombre del documento</label><input id="docTitle" required></div><div><label>Código</label><input id="docCode" placeholder="Ej. A06"></div><div><label>Categoría</label><select id="docCategory">${opt(['Planos','RDI','Fichas técnicas','Catálogos','EETT','Certificados','Informes','Otros'])}</select></div><div><label>Revisión</label><input id="docRev" placeholder="Rev. 0"></div><div><label>Referencia de aprobación técnica</label><input id="docApproval" placeholder="N° o fecha de aprobación"></div><div><label>Archivo</label><input id="docFile" type="file" required></div></div><label><input id="docCurrent" type="checkbox" style="width:auto"> Publicar como documento vigente (requiere respaldo técnico)</label><button class="primary">Subir documento</button></form><hr>`:''}<div class="scroll"><table><tr><th>Documento</th><th>Tipo</th><th>Revisión</th><th>Acción</th></tr>${S.documents.slice().reverse().map(d=>`<tr><td><b>${esc(d.code||'')} ${esc(d.title)}</b> ${d.is_current?badge('Vigente'):''}</td><td>${esc(d.category)}</td><td>${esc(d.revision)}</td><td><button onclick="viewFile('${esc(d.file_path)}')">Abrir</button></td></tr>`).join('')}</table></div>`)+card('RDI · Gestión centralizada',`<form onsubmit="createRdi(event)"><label>Asunto de la consulta</label><input id="rdiSubject" required><label>Descripción y antecedentes</label><textarea id="rdiDetail" required></textarea><label>Especialidad</label><select id="rdiSpecialty">${opt(['Arquitectura','Estructura','Sanitario','Eléctrico','Climatización','Impermeabilización','Otra'])}</select><button class="primary">${technical()?'Registrar RDI / propuesta':'Proponer consulta a Oficina Técnica'}</button></form><hr><div class="scroll"><table><tr><th>RDI</th><th>Especialidad</th><th>Estado</th><th>Acción</th></tr>${S.rdis.slice().reverse().map(r=>`<tr><td><b>${esc(r.number||'Sin número')} · ${esc(r.subject)}</b><div class="muted">${esc(r.description)}</div></td><td>${esc(r.specialty)}</td><td>${badge(r.status)}</td><td>${technical()?`<button onclick="manageRdi('${r.id}')">Gestionar</button>`:''}</td></tr>`).join('')}</table></div>`)}
async function uploadDocument(e){e.preventDefault();const file=$('#docFile').files[0];if(!file)return;let path=null;try{path=await uploadFile(file,'documentos');const payload={title:val('docTitle'),code:val('docCode'),category:val('docCategory'),revision:val('docRev'),approval_reference:val('docApproval')||null,is_current:$('#docCurrent').checked&&!!val('docApproval'),file_path:path,mime_type:file.type};const {error}=await db.from('documents').insert(payload);if(error)throw error;await reload();toast('Documento subido y registrado correctamente');}catch(e){if(path)await db.storage.from('checkobra-files').remove([path]);toast('Error al subir documento: '+e.message)}}
async function createRdi(e){e.preventDefault();await mutate('rdis',{subject:val('rdiSubject'),description:val('rdiDetail'),specialty:val('rdiSpecialty'),status:'Propuesta',submitted_by:S.user.id})}
async function manageRdi(id){const r=S.rdis.find(x=>x.id===id);if(!r)return;const next=prompt('Estado: Borrador / Enviada / En revisión / Respondida / Cerrada',r.status);if(!['Borrador','Enviada','En revisión','Respondida','Cerrada'].includes(next))return;const reply=prompt('Respuesta o referencia formal (si corresponde)',r.reply||'');await mutate('rdis',{status:next,reply,formalized_by:S.user.id,sent_at:next==='Enviada'?new Date().toISOString():r.sent_at,closed_at:next==='Cerrada'?new Date().toISOString():null},'update',id)}
function myWork(){const name=S.profile?.full_name;return card('Mi trabajo',`<p>Usuario: <b>${esc(name)}</b> · ${esc(role())}</p><div class="grid">${metric('Compromisos pendientes',S.tasks.filter(t=>t.owner_id===S.user.id&&t.status!=='Validada').length)}${metric('Observaciones asignadas',S.issues.filter(i=>i.owner_id===S.user.id&&i.status!=='Cerrada').length)}${metric('Correcciones por verificar',S.issues.filter(i=>i.owner_id===S.user.id&&i.status==='Corregida').length)}</div>`)+card('Observaciones a mi cargo',S.issues.filter(i=>i.owner_id===S.user.id&&i.status!=='Cerrada').map(issueCard).join('')||'<p class="muted">No hay observaciones pendientes asignadas.</p>')+card('Mis partidas',S.trades.filter(t=>t.owner_id===S.user.id||t.owner_name===name).map(t=>`<span class="tag">${esc(t.name)}</span> `).join('')||'<p class="muted">Sin partidas asignadas.</p>')}
function adminView(){if(!manager())return card('Acceso restringido','Solo Jefatura.');return card('Estado de catálogos',`<div class="grid">${metric('Departamentos',S.units.length)}${metric('Partidas',S.trades.length)}${metric('Responsables',S.staff.length)}${metric('Estados importados del Excel',S.excelStatus.length)}</div><p class="muted">Si un catálogo aparece vacío, ejecutar MIGRACION_Y_CARGA_2_2.sql en Supabase SQL Editor.</p>`)+card('Administración · Partidas y responsables',`<p class="notice">Los cambios de responsable son inmediatos para los nuevos registros. Las observaciones y tareas ya asignadas mantienen su responsable hasta ser reasignadas explícitamente.</p><div class="scroll"><table><tr><th>Partida</th><th>Frente</th><th>Responsable</th><th>Guardar</th></tr>${S.trades.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.front)}</td><td><select id="owner-${t.id}">${opt([['','Sin asignar'],...S.staff.filter(p=>p.active).map(p=>[p.full_name,p.full_name])],t.owner_name)}</select></td><td><button onclick="assignTrade('${t.id}')">Guardar</button></td></tr>`).join('')}</table></div>`)+card('Usuarios precargados · Invitaciones seguras',`<p>Los nombres y roles ya están definidos. Para activar cada cuenta es necesario indicar su correo real, cargarlo en <code>invitation_roster</code> y enviar la invitación desde Supabase Auth. Nunca se distribuyen claves genéricas.</p><div class="scroll"><table><tr><th>Usuario</th><th>Rol</th><th>Cuenta activada</th></tr>${STAFF.map(([n,r])=>`<tr><td>${esc(n)}</td><td>${esc(r)}</td><td>${S.people.some(p=>p.full_name===n)?'Sí':'Pendiente de invitación'}</td></tr>`).join('')}</table></div>`)+card('Importación de línea base',`<p>Importa registros de programación revisados, no cantidades de avance no verificadas.</p><label>Archivo CSV con columnas: trade_label,location,start_date,end_date,planned_percent,reported_percent,source_sheet,source_row</label><input type="file" accept=".csv,text/csv" id="baselineCsv"><button onclick="importBaseline()">Importar CSV revisado</button><p class="muted">El programa Excel original se incluye en el paquete. Los porcentajes de ejecución requieren confirmación y no se convierten automáticamente en avance físico.</p>`)}
async function assignTrade(id){const name=val('owner-'+id);await mutate('trades',{owner_id:staffProfile(name),owner_name:name||null,updated_at:new Date().toISOString()},'update',id)}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);const sep=lines[0].includes(';')?';':',';const head=lines.shift().split(sep).map(s=>s.trim());return lines.map(line=>{const cells=line.split(sep);return Object.fromEntries(head.map((h,i)=>[h,(cells[i]||'').trim()]))})}
async function importBaseline(){const f=$('#baselineCsv').files[0];if(!f)return toast('Selecciona un CSV');const rows=parseCSV(await f.text()).filter(x=>x.trade_label).slice(0,1500).map(r=>({trade_label:r.trade_label,location:r.location||null,start_date:r.start_date||null,end_date:r.end_date||null,planned_percent:r.planned_percent?Number(r.planned_percent):null,reported_percent:r.reported_percent?Number(r.reported_percent):null,source_sheet:r.source_sheet||null,source_row:r.source_row?Number(r.source_row):null,verified:false}));try{for(let i=0;i<rows.length;i+=100){const {error}=await db.from('schedule_baseline').insert(rows.slice(i,i+100));if(error)throw error}await reload();toast(`${rows.length} filas importadas como NO verificadas`)}catch(e){toast(e.message)}}
async function boot(){if(!configured){render();return}const {data}=await db.auth.getSession();S.user=data.session?.user||null;db.auth.onAuthStateChange(async(_event,session)=>{S.user=session?.user||null;if(S.user)await reload();else render()});if(S.user)await reload();else render();db.channel('checkobra-live').on('postgres_changes',{event:'*',schema:'public'},()=>reload()).subscribe();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('/sw.js').catch(console.warn)}
boot();
